file.content:
    # Header row + separator row are the two lines right after the match; insert after those.
    $insertAt = $ideaHeaderIndex + 2
    $newLines = $plannerLines[0..($insertAt - 1)] + $newRow + $plannerLines[$insertAt..($plannerLines.Count - 1)]
    Set-Content -Path $plannerPath -Value $newLines -Encoding utf8
    Write-Host "Added row to PLANNER.md Idea table."
} else {
    Write-Warning "Could not find the Idea table in PLANNER.md — add the row manually:`n$newRow"
}

Write-Host "Created projects/$Name from template."
Write-Host "Next: open $folderLink and fill in the brief."
